public int checkWifiName(Editable editable) {
    boolean z = false;
    if (editable == null || editable.length() == 0) {
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiNameErrorTip.setText(R.string.wifi_name_not_allow_empty);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiNameErrorTip.setVisibility(0);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).btnSave.setEnabled(false);
        return 0;
    }
    if (editable.length() > 30) {
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiNameErrorTip.setText(R.string.wifi_name_not_allow_exceed_max_lenght);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiNameErrorTip.setVisibility(0);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).btnSave.setEnabled(false);
        return -2;
    }
    ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiNameErrorTip.setVisibility(8);
    Editable text = ((FragmentConfigDeviceNetManagerBinding) this.binding).layoutInputWifiPassword.etInput.getText();
    String strTrim = text != null ? text.toString().trim() : "";
    Button button = ((FragmentConfigDeviceNetManagerBinding) this.binding).btnSave;
    if (strTrim.length() >= 8 && strTrim.length() <= 30) {
        z = true;
    }
    button.setEnabled(z);
    return 1;
}
